from fractions import Fraction

def validate_identity(expected, observed, terminals):
    problems = []
    seen = {}
    for rid, val, attempt, epoch in observed:
        if rid in seen:
            problems.append(('duplicate_result', rid))
        else:
            seen[rid] = (val, attempt, epoch)
    exp = set(expected)
    obs = set(seen)
    for rid in sorted(exp - obs):
        problems.append(('missing_result', rid))
    for rid in sorted(obs - exp):
        problems.append(('extra_result', rid))
    for rid in sorted(exp & obs):
        if seen[rid][0] != expected[rid]:
            problems.append(('content_mismatch', rid))
    term = {}
    for t in terminals:
        rid = t['rid']
        if rid in term:
            problems.append(('duplicate_terminal', rid))
        else:
            term[rid] = t
    for rid in sorted(exp):
        if rid not in term:
            problems.append(('missing_terminal', rid))
        elif term[rid]['status'] not in ('ok', 'cancelled', 'error'):
            problems.append(('bad_terminal_status', rid))
    for rid in sorted(set(term) - exp):
        problems.append(('extra_terminal', rid))
    return problems

def validate_distribution(p, allowed):
    problems = []
    for i, x in enumerate(p):
        if x < 0:
            problems.append(('negative_probability', i))
    total = sum(p, Fraction(0))
    if total != 1:
        problems.append(('sum_not_one', total))
    support = set()
    for i, x in enumerate(p):
        if x > 0:
            support.add(i)
    if not support <= allowed:
        problems.append(('support_outside_allowed', tuple(sorted(support - allowed))))
    return problems

def validate_trace(events, expected_body):
    problems = []
    starts = 0
    terminals = 0
    body = b''
    last_seq = -1
    state = 'init'
    for e in events:
        kind = e['type']
        if kind == 'start':
            if state != 'init':
                problems.append(('start_after_start',))
            starts += 1
            state = 'started'
        elif kind == 'data':
            if state != 'started':
                problems.append(('data_outside_started',))
            seq = e['seq']
            if seq != last_seq + 1:
                problems.append(('bad_sequence', last_seq, seq))
            last_seq = seq
            body += e['body']
        elif kind in ('end', 'error'):
            terminals += 1
            state = 'terminal'
        else:
            problems.append(('unknown_event', kind))
    if starts != 1:
        problems.append(('start_count', starts))
    if terminals != 1:
        problems.append(('terminal_count', terminals))
    if body != expected_body:
        problems.append(('body_mismatch', len(body), len(expected_body)))
    return problems

def validate_partition(total, free, active, inflight, retained, quarantined):
    parts = [free, active, inflight, retained, quarantined]
    ids = []
    for part in parts:
        ids.extend(part)
    problems = []
    if len(ids) != len(set(ids)):
        problems.append(('duplicate_or_shared_count',))
    if set(ids) != set(total):
        missing = set(total) - set(ids)
        extra = set(ids) - set(total)
        problems.append(('union_mismatch', tuple(sorted(missing)), tuple(sorted(extra))))
    return problems

def validate_quiescent(active, inflight, retained, quarantined, free, total):
    problems = []
    if inflight or quarantined:
        problems.append(('not_quiescent',))
    if active:
        problems.append(('active_remains',))
    if not problems and set(free) != set(total) - set(retained):
        problems.append(('free_retained_mismatch',))
    return problems

def ref_model(tokens, weights):
    total = Fraction(0)
    for i in range(len(tokens)):
        total += weights[i] * tokens[i]
    return total

def chunked_model(tokens, weights, chunks, reset_positions):
    total = Fraction(0)
    for start, end in chunks:
        for i in range(start, end):
            j = i - start if reset_positions else i
            total += weights[j] * tokens[i]
    return total

def stable_top1(z, eps):
    order = sorted(range(len(z)), key=lambda i: z[i], reverse=True)
    margin = z[order[0]] - z[order[1]]
    return margin > 2 * eps, margin

def cdf_sample(p, u):
    c = Fraction(0)
    for i, pi in enumerate(p):
        c += pi
        if u < c:
            return i
    return len(p) - 1

def main():
    checks = 0
    negative = 0
    failures = []

    def clean(name, problems):
        nonlocal checks
        checks += 1
        if problems:
            failures.append((name, problems))

    def reject(name, problems, tag):
        nonlocal checks, negative
        checks += 1
        if not any(p[0] == tag for p in problems):
            failures.append((name, problems))
        else:
            negative += 1

    exp = {'A': Fraction(17), 'B': Fraction(99)}
    terms = [{'rid': 'A', 'status': 'ok'}, {'rid': 'B', 'status': 'ok'}]
    clean('identity_expected_set', validate_identity(exp, [('A', Fraction(17), 1, 1), ('B', Fraction(99), 1, 1)], terms))
    reject('identity_alias_negative', validate_identity(exp, [('A', Fraction(17), 1, 1), ('B', Fraction(17), 1, 1)], terms), 'content_mismatch')
    reject('identity_duplicate_terminal_negative', validate_identity(exp, [('A', Fraction(17), 1, 1), ('B', Fraction(99), 1, 1)], [{'rid': 'A', 'status': 'ok'}, {'rid': 'A', 'status': 'ok'}, {'rid': 'B', 'status': 'ok'}]), 'duplicate_terminal')
    reject('identity_missing_result_negative', validate_identity(exp, [('A', Fraction(17), 1, 1)], terms), 'missing_result')

    tokens = [Fraction(1), Fraction(2), Fraction(3), Fraction(4)]
    weights = [Fraction(1), Fraction(3), Fraction(5), Fraction(7)]
    ref = ref_model(tokens, weights)
    good = chunked_model(tokens, weights, [(0, 2), (2, 4)], False)
    bad = chunked_model(tokens, weights, [(0, 2), (2, 4)], True)
    checks += 1
    if good != ref:
        failures.append(('chunk_global_positions', good, ref))
    checks += 1
    if bad == ref:
        failures.append(('chunk_reset_not_detected', bad))
    else:
        negative += 1
    checks += 1
    if ref_model([], []) != Fraction(0):
        failures.append(('empty_reference',))

    p = [Fraction(1, 5), Fraction(3, 10), Fraction(1, 2)]
    clean('distribution_normalized', validate_distribution(p, {0, 1, 2}))
    reject('distribution_negative_negative', validate_distribution([Fraction(-1, 10), Fraction(3, 5), Fraction(1, 2)], {0, 1, 2}), 'negative_probability')
    reject('distribution_sum_negative', validate_distribution([Fraction(1, 5), Fraction(3, 10), Fraction(2, 5)], {0, 1, 2}), 'sum_not_one')
    reject('distribution_support_negative', validate_distribution([Fraction(0), Fraction(0), Fraction(1)], {0, 1}), 'support_outside_allowed')
    checks += 1
    if cdf_sample(p, Fraction(0)) != 0:
        failures.append(('cdf_zero',))
    checks += 1
    if cdf_sample(p, Fraction(1, 5)) != 1:
        failures.append(('cdf_boundary',))
    checks += 1
    if cdf_sample(p, Fraction(99, 100)) != 2:
        failures.append(('cdf_tail',))

    events = [{'type': 'start'}, {'type': 'data', 'seq': 0, 'body': b'ab'}, {'type': 'data', 'seq': 1, 'body': b'cd'}, {'type': 'end'}]
    clean('protocol_ordered', validate_trace(events, b'abcd'))
    reject('protocol_duplicate_terminal_negative', validate_trace(events + [{'type': 'end'}], b'abcd'), 'terminal_count')
    reject('protocol_data_after_terminal_negative', validate_trace([{'type': 'start'}, {'type': 'data', 'seq': 0, 'body': b'ab'}, {'type': 'end'}, {'type': 'data', 'seq': 1, 'body': b'cd'}], b'abcd'), 'data_outside_started')
    reject('protocol_missing_terminal_negative', validate_trace([{'type': 'start'}, {'type': 'data', 'seq': 0, 'body': b'ab'}], b'ab'), 'terminal_count')

    total = [0, 1, 2, 3, 4, 5]
    clean('resource_quiescent_accounting', validate_partition(total, [0, 1, 2, 3, 4, 5], [], [], [], []))
    clean('resource_inflight_accounting', validate_partition(total, [2, 3, 4, 5], [0], [1], [], []))
    clean('resource_quiescent_status', validate_quiescent([], [], [], [], [0, 1, 2, 3, 4, 5], total))
    reject('resource_not_quiescent_negative', validate_quiescent([0], [1], [], [], [2, 3, 4, 5], total), 'not_quiescent')
    reject('resource_forget_inflight_negative', validate_partition(total, [2, 3, 4, 5], [0], [], [], []), 'union_mismatch')
    reject('resource_double_shared_negative', validate_partition(total, [1, 2, 3, 4, 5], [0, 0], [], [], []), 'duplicate_or_shared_count')

    checks += 1
    ok, margin = stable_top1([Fraction(5), Fraction(4)], Fraction(2, 5))
    if not ok:
        failures.append(('margin_certificate', margin))
    checks += 1
    ok2, _ = stable_top1([Fraction(5), Fraction(4)], Fraction(3, 5))
    if ok2:
        failures.append(('margin_should_be_unproven',))

    if failures:
        print('FAIL')
        for item in failures:
            print(item)
        raise SystemExit(1)
    print('PASS: CPU logical oracle checks')
    print('checks=', checks)
    print('negative_controls_detected=', negative)
    print('scope=CPU logical model only; no engine, GPU, or performance measurement')

if __name__ == '__main__':
    main()
